// SQLiteMigrations returns the list of migrations the current
// skygate binary knows about for the SQLite backend. Used by
// `skygate migrate status` (B213 CLI) and the audit page.
func SQLiteMigrations() []MigrationEntry {
	out := make([]MigrationEntry, len(sqliteMigrations))
	copy(out, sqliteMigrations)
	return out
}

// MigrateSQLite runs every SQLite migration in version order,
// records each successful application in applied_migrations
// (idempotent — first-write-wins on the version primary key), and
// returns the first error encountered. The migration state is
// whatever the DB was left in.
//
// Mirror of MigratePostgres in driver_postgres.go. The two
// functions MUST stay in lock-step — same metadata, same Run
// ordering, same bookkeeping. Only the DDL inside the migrateVxxx
// functions differs.
func MigrateSQLite(d *sql.DB) error {
	// Ensure the applied_migrations tracking table exists BEFORE
	// we try to write to it. ensureMigrationTrackingTable is
	// dialect-aware (Task 6: it dispatches on BackendOf(d)).
	if err := ensureMigrationTrackingTable(d); err != nil {
		return fmt.Errorf("ensure applied_migrations table: %w", err)
	}
	for _, e := range sqliteMigrations {
		if err := e.Run(d); err != nil {
			return fmt.Errorf("migration v%d (%s): %w", e.Version, e.Name, err)
		}
		versionStr := fmt.Sprintf("v0.%d", e.Version)
		if err := RecordMigrationApplied(d, e.Version, "", e.SourceFile, versionStr); err != nil {
			// Mirror the PG-side policy: log + continue. The
			// migration already ran, so the schema is correct;
			// the bookkeeping is out of sync. Re-running on
			// next boot would re-apply the migration (idempotent
			// IF NOT EXISTS guards) and re-attempt the
			// bookkeeping insert.
			log.Printf("migrate: WARNING: record v%d (%s) failed: %v (continuing — schema is correct, bookkeeping is out of sync)", e.Version, e.Name, err)
		}
	}
	return nil
}

// ApplyMigrations runs the dialect-appropriate migration chain
// against the given *sql.DB. Dispatches on `kind`:
//
//   - DialectSQLite: MigrateSQLite
//   - DialectPostgres: MigratePostgres
//   - DialectUnknown: error
//
// The kind argument is the canonical "which migration set to run"
// value. The *sql.DB's actual backend (BackendOf(db)) is NOT
// consulted here — caller is responsible for ensuring the kind
// matches the DB (the typical case is DetectDSN → OpenWithDialect
// which returns both the kind and the open *sql.DB).
//
// Use this function when you have a *sql.DB and want to ensure
// the schema is fully migrated. Use the dialect-specific
// MigrateSQLite / MigratePostgres when you already know the kind.
func ApplyMigrations(db *sql.DB, kind DialectKind) error {
	switch kind {
	case DialectSQLite:
		return MigrateSQLite(db)
	case DialectPostgres:
		return MigratePostgres(db)
	default:
		return fmt.Errorf("db.ApplyMigrations: unknown dialect kind %v", kind)
	}
}
